package com.hutka.backend.ai.service;

import java.math.BigDecimal;

/**
 * Знания AI-помощника о платформе. Каждый пункт — пересказ Hutka.md; номер раздела указан в скобках, чтобы при правке ТЗ
 * было видно, что обновить здесь. Если правило в ТЗ изменилось, а текст ниже нет — AI будет отвечать устаревшим.
 */
final class AiKnowledgeBase {

    private AiKnowledgeBase() {}

    static String text(BigDecimal commissionPercent, BigDecimal ratingThreshold, int minRatingsCount) {
        return """
                ЗНАНИЯ О ПЛАТФОРМЕ
                Общее (1, 2): HUTKA — маркетплейс: владельцы сдают свои машины, арендаторы берут их дешевле прокатных контор, платформа берёт комиссию. Старт — Минск. Роли: гость, пользователь, администратор. «Партнёр» — статус поверх пользователя: один человек может и арендовать, и сдавать. Гость видит каталог и карту без бронирования.
                Регистрация (3.1): имя, фамилия, email (подтверждается 6-значным кодом), телефон (без подтверждения), дата рождения (минимум 18 лет), пароль от 8 символов. Сброс пароля (3.3): ссылка на email, действует 1 час; смена пароля из настроек использует тот же сценарий «Забыли пароль».
                Верификация (3.2): для бронирования нужно указать серию и номер водительского удостоверения и дату выдачи; администратор проверяет до 24 часов (проверяется формат и заполненность, фото не требуется). При отклонении придёт причина, данные можно подать повторно. Бронирование, тест ПДД и групповые поездки доступны только после статуса verified. Требований к стажу нет.
                Каталог (4): фильтры — топливо, коробка, число мест, тип кузова, цена за час; сортировка — цена, рейтинг, расстояние; поиск по марке и модели; режимы — список и карта. Координаты машины определяются по адресу один раз (не GPS-трекинг).
                Бронирование (6): выберите машину, время начала и возврата. Пересекающиеся слоты недоступны. Instant Book — бронь подтверждается сразу; Request to Book — партнёр отвечает до 6 часов, иначе заявка отклоняется автоматически; для Request to Book начало не раньше чем через 6 часов. Залог сейчас не удерживается, реальных платежей пока нет — расчёт стоимости и статусы уже работают. Перед началом поездки обязательно фото машины «до», перед завершением — «после» (основа для споров).
                Отмена и неявка (6.1, 6.4, 6.5): до начала поездки отмена бесплатна; после начала — только завершение. Если поездка не начата в течение 1 часа после запланированного времени, бронь отменяется автоматически. Если партнёр не обеспечил машину, бронь отменяется без последствий для арендатора, скидка за тест ПДД возвращается; партнёру начисляется страйк, 3 страйка за 30 дней скрывают машину до проверки администратором.
                Стоимость (6.3): часы в пределах планового времени × цена за час + просроченные часы × цена за час × 1,5. Просрочка больше 3 часов без связи с арендатором передаётся администратору в раздел «Споры». Договор аренды в PDF приходит на email после завершения поездки, повторно доступен в кабинете (6.6).
                Тест ПДД (5): необязательный, после верификации. 10 вопросов из базы в 200, до 1 ошибки, 15 минут. В месячном цикле 3 попытки, подряд без паузы. Успех даёт скидку 10%% на следующее бронирование, она действует 3 дня и сгорает после использования; после успеха новый цикл открывается через месяц. Если все 3 попытки провалены — новый цикл через месяц после последней.
                Рейтинг (7): после аренды стороны ставят оценку 1–5 и комментарий. Правило порога действует только при минимум %d оценках. Арендатор с рейтингом ниже %s не может бронировать (можно обратиться в поддержку с апелляцией — администратор рассмотрит вручную); машина с рейтингом ниже порога выпадает из топа выдачи, но остаётся доступной.
                Групповые поездки (8): социальный слой для координации — маршрут, участники, чат. Каждый участник бронирует свою машину отдельно; присоединение бронь не создаёт. Организатор может закрыть набор или отменить поездку (уже созданные брони отменяются участниками отдельно).
                Партнёр (9, 10): чтобы стать партнёром, подайте заявку на машину после верификации. Требования: год выпуска не ранее 2014, пробег не более 200 000 км, техосмотр не просрочен, минимум 5 фото, адрес, цена за час, номера техпаспорта и полиса. Модерация до 24 часов, при отклонении придёт причина. Партнёр может менять цену, расписание, адрес, режим бронирования, описание и фото; изменения цены и расписания не влияют на уже подтверждённые брони. Скрыть машину можно всегда; удалить — только если не было завершённых поездок. Адрес нельзя менять при активных бронях.
                Деньги партнёра (15, 10.6): комиссия платформы — %s%% с суммы за часы в пределах плана; доплата за просрочку комиссией не облагается. Реальные выплаты и эквайринг (Bepaid) пока не запущены — раздел показывает расчётные значения.
                Уведомления (13): в реальном времени и в истории. Поддержка (14): тикеты с категориями «Бронирование», «Оплата и выплаты», «Техническая проблема», «Спор», «Другое»; срочные поднимаются в начало очереди; закрытый тикет можно переоткрыть в течение 7 дней.
                Ограничения самого AI (11.4): ты не решаешь споры и не обещаешь компенсации.
                """.formatted(minRatingsCount, ratingThreshold.stripTrailingZeros().toPlainString(),
                commissionPercent.stripTrailingZeros().toPlainString());
    }
}
